(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ArcadeRound=api})(typeof window==='object'?window:this,()=>{
'use strict';const durations=[120,180,240,300];const valid=n=>durations.includes(Number(n))?Number(n):120;
class Clock{constructor(){this.duration=120;this.elapsed=0;this.running=false;this.enabled=false}start(seconds,demo=false){this.duration=valid(seconds);this.elapsed=0;this.enabled=!demo;this.running=!demo}tick(dt,playing=true){if(!this.running||!playing||!Number.isFinite(dt)||dt<=0)return false;this.elapsed=Math.min(this.duration,this.elapsed+dt);if(this.remaining<=1e-7){this.running=false;return true}return false}stop(){this.running=false}get remaining(){return Math.max(0,this.duration-this.elapsed)}}
function format(n){n=Math.ceil(Math.max(0,n-1e-7));return Math.floor(n/60)+':'+String(n%60).padStart(2,'0')}
function mount({settings,hud,output}={}){const clock=new Clock(),label=document.createElement('label');label.className='roundChoice';label.textContent='Game length ';const select=document.createElement('select');select.setAttribute('aria-label','Game length');for(const seconds of durations){const option=document.createElement('option');option.value=seconds;option.textContent=seconds/60+' minutes';select.append(option)}let saved=120;try{saved=valid(localStorage.getItem('arcadeRoundSeconds.v1'))}catch{}select.value=String(saved);select.onchange=()=>{try{localStorage.setItem('arcadeRoundSeconds.v1',String(valid(select.value)))}catch{}if(!clock.running){clock.duration=valid(select.value);clock.elapsed=0;draw()}};label.append(select);const host=document.querySelector(settings)||document.body;host.append(label);const badge=output?document.getElementById(output):document.createElement('span');if(!output){badge.className='roundClock';badge.setAttribute('role','timer');badge.setAttribute('aria-label','Time remaining');(document.querySelector(hud)||host).append(badge)}
function draw(){badge.textContent=format(clock.remaining);badge.classList.toggle('roundUrgent',clock.enabled&&clock.remaining<=20);badge.setAttribute('aria-label','Time remaining '+format(clock.remaining))}
clock.duration=saved;draw();document.addEventListener('arcade-practice-done',()=>clock.stop());return{clock,select,start(demo=false){clock.start(select.value,demo);badge.hidden=demo;draw();return clock.enabled?clock.duration:0},tick(dt,playing=true){const ended=clock.tick(dt,playing&&!document.hidden);draw();return ended},stop(){clock.stop();draw()},get enabled(){return clock.enabled},get running(){return clock.running},get elapsed(){return clock.elapsed},get duration(){return clock.duration},get remaining(){return clock.remaining}}}
return{Clock,format,mount,durations};});
